'use strict';
const {departments,documents,checkedAt}=window.POLICY_DATA;
const $=s=>document.querySelector(s), $$=s=>Array.from(document.querySelectorAll(s));
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function safeURL(u){try{const v=new URL(u,location.href);return /^https?:$/.test(v.protocol)?v.href:'#';}catch{return '#';}}
const link=(u,t,cls='')=>`<a href="${esc(safeURL(u))}" target="_blank" rel="noopener noreferrer" class="${cls}">${esc(t)} <span aria-hidden="true">↗</span></a>`;
const deptById=Object.fromEntries(departments.map(d=>[d.id,d]));
const state={dept:'all',collection:'all',q:'',topic:'all',series:'all',year:'all',sort:'department',view:'documents'};
const docsFor=d=>documents.filter(x=>x.departmentId===d.id);
let activeDoc=null,toastTimer;
const badge=d=>`<span class="verification ${d.sourceClass==='reprint'?'reprint':''}">${d.sourceClass==='ministry'?'官方原文':'官方转载'}</span>`;
const dateLabel=d=>(d.date||'').replaceAll('-','.');
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2400);}
function reset(){Object.assign(state,{dept:'all',collection:'all',q:'',topic:'all',series:'all',year:'all',sort:'department'});$('#search').value='';$('#series').value='all';$('#year').value='all';$('#sort').value='department';render();}
function documentMatches(d){if(state.dept!=='all'&&d.departmentId!==state.dept)return false;if(state.collection!=='all'&&state.collection!==d.collection)return false;if(state.series!=='all'&&state.series!==d.series)return false;if(state.year!=='all'&&String(d.year)!==state.year)return false;if(state.topic!=='all'&&!d.topics.includes(state.topic))return false;if(state.q){const hay=[d.title,d.number,deptById[d.departmentId].name,d.summary,d.tags.join(' '),d.body].join(' ').toLowerCase();if(!hay.includes(state.q.toLowerCase()))return false;}return true;}
function card(d){return `<button class="file-card" data-doc="${esc(d.id)}" aria-label="阅读${esc(d.number)}：${esc(d.title)}"><div class="card-top"><span class="card-dept"><span>${d.departmentId}</span>${esc(deptById[d.departmentId].shortName)}</span>${badge(d)}</div><div class="file-number">${esc(d.number)} <span class="collection-label">${d.isFirst?'2026 一号文件':'专题政策'}</span></div><h3>${esc(d.shortTitle||d.title.replace(/^教育部办公厅等[一二三四五六七八九十]+部门关于|^教育部等[一二三四五六七八九十]+部门关于|^教育部办公厅关于|^教育部关于/,'').replace(/的通知$|的意见$|的决定$/,''))}</h3><p>${esc(d.summary)}</p><div class="card-tags"><span class="nature">${esc(d.nature)}</span>${d.tags.slice(0,3).map(t=>`<span>${esc(t)}</span>`).join('')}</div><div class="card-bottom"><span>${dateLabel(d)} · 成文</span><span class="read-more">站内阅读全文 <b>↗</b></span></div></button>`;}
function renderSidebar(){$('#all-count').textContent=documents.length;$('#all-departments').classList.toggle('selected',state.dept==='all');$('#all-departments').setAttribute('aria-pressed',state.dept==='all');$('#department-list').innerHTML=`<button class="dept-item mobile-all ${state.dept==='all'?'selected':''}" data-dept="all"><span>全部司局</span><span class="dept-count">${documents.length}</span></button>`+departments.map(d=>`<button class="dept-item ${state.dept===d.id?'selected':''}" data-dept="${d.id}" aria-pressed="${state.dept===d.id}" title="${esc(d.name)}"><span>${esc(d.shortName)}</span><span class="dept-count">${docsFor(d).length}</span></button>`).join('');}
function render(){renderSidebar();$$('[data-collection]').forEach(b=>{b.classList.toggle('active',b.dataset.collection===state.collection);b.setAttribute('aria-pressed',b.dataset.collection===state.collection);});$$('[data-topic]').forEach(b=>{b.classList.toggle('active',b.dataset.topic===state.topic);b.setAttribute('aria-pressed',b.dataset.topic===state.topic);});$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===state.view));const coverage=state.view==='coverage';$('#catalog-title').textContent=coverage?'关注司局目录':state.dept==='all'?'重点政策文件库':deptById[state.dept].shortName;$('#results').hidden=coverage;$('#coverage-view').hidden=!coverage;$('.results-note').hidden=coverage;const filtered=documents.filter(documentMatches).sort((a,b)=>{if(state.sort==='department')return departments.findIndex(d=>d.id===a.departmentId)-departments.findIndex(d=>d.id===b.departmentId)||Number(b.isFirst)-Number(a.isFirst)||b.date.localeCompare(a.date);return state.sort==='newest'?b.date.localeCompare(a.date):a.date.localeCompare(b.date);});$('#clear-button').hidden=state.dept==='all'&&state.collection==='all'&&!state.q&&state.topic==='all'&&state.series==='all'&&state.year==='all';if(!coverage){$('#results-count').textContent=`${filtered.length} 份政策 · 全部支持站内阅读`;$('#results').innerHTML=filtered.map(card).join('');if(!filtered.length)$('#results').innerHTML='<div class="empty-state"><strong class="empty-title">没有符合条件的政策</strong><p>试试更短的关键词，或清除司局、主题和年份筛选。</p><button class="button button-ghost" data-reset>清除全部筛选</button></div>';}else{const ds=departments.filter(d=>filtered.some(x=>x.departmentId===d.id));$('#results-count').textContent=`${ds.length} 个司局 · ${filtered.length} 份可读政策`;$('#coverage-view').innerHTML=ds.length?`<div class="table-wrap"><table class="coverage-table"><thead><tr><th>索引</th><th>关注司局</th><th>2026 一号文</th><th>专题政策</th></tr></thead><tbody>${ds.map(d=>{const n=filtered.filter(x=>x.departmentId===d.id);return `<tr><td>${d.id}</td><td class="coverage-name"><button data-coverage="${d.id}">${esc(d.name)} ↗</button></td><td>${n.filter(x=>x.isFirst).length}</td><td>${n.filter(x=>!x.isFirst).length}</td></tr>`;}).join('')}</tbody></table></div>`:'<div class="empty-state"><strong class="empty-title">没有符合条件的司局</strong><button class="button button-ghost" data-reset>清除筛选</button></div>';}}
function showDialog(d){if(!d.open)d.showModal();document.body.classList.add('modal-open');d.scrollTop=0;}
function bodyHTML(body){let i=0;const headings=[];const parts=body.replace(/\r/g,'').split(/\n\s*\n/).filter(p=>p.trim());const html=parts.map(block=>{if(block.length<100&&(/^[一二三四五六七八九十]+、|^第[一二三四五六七八九十]+章|^[0-9]+\s+[^\d]/.test(block.trim())||/^附件[：:]/.test(block.trim()))){const id='section-'+i++;headings.push({id,title:block.trim()});return `<h4 id="${id}">${esc(block.trim())}</h4>`;}return `<p>${esc(block.trim())}</p>`;}).join('');return (headings.length>2?`<details class="body-outline"><summary>展开正文目录 (${headings.length})</summary><div>${headings.map(h=>`<button data-section="${h.id}">${esc(h.title)}</button>`).join('')}</div></details>`:'')+`<div class="body-text">${html}</div>`;}
function localAction(u,title='站内预览原件'){return u&&/\.pdf$/i.test(u)?`<button class="button button-ghost" data-pdf="${esc(u)}">${esc(title)}</button>`:u?`<a class="button button-ghost" href="${esc(safeURL(u))}" download>下载本站留存文件 ↓</a>`:'';}
function showDocument(id){const d=documents.find(x=>x.id===id);if(!d)return;activeDoc=d;$('#detail-position').textContent=d.number;const dept=deptById[d.departmentId];const meta=[['业务司局',dept.name],['发文机构',d.issuer],['成文日期',d.date+(d.sourceClass==='reprint'?'（公开原件）':'')],['发布日期',d.publishedDate||'未确认'],['文号系列',d.series+' · '+(d.isFirst?'2026 一号文件':'专题政策')],['文字来源',d.sourceType||d.sourceLabel]];const sources=[{title:d.sourceLabel,url:d.url},...(d.sources||[]),...(d.supportingSources||[])].filter((s,i,arr)=>arr.findIndex(x=>x.url===s.url)===i);const sourceRows=sources.map(s=>`<div class="source-row"><small>出处核查</small>${link(s.url,s.title)}<div class="url">${esc(s.url)}</div></div>`).join('');const attachments=d.attachments.map((a,i)=>`<div class="source-row"><small>附件 ${String(i+1).padStart(2,'0')}</small><h4 class="attachment-title">${esc(a.title||a.name||'附件')}</h4><div class="source-actions">${a.body?`<button class="button button-ghost" data-attachment="${i}">站内阅读附件</button>`:''}${localAction(a.localPreviewURL||a.localURL)}${link(a.url,'原站附件','button button-ghost')}</div></div>`).join('');const preview=d.localPreviewURL||d.localOriginalURL;
$('#detail-content').innerHTML=`<div class="detail-meta-top"><span class="dept-label">${d.departmentId} / ${esc(dept.shortName)}</span>${badge(d)}<span class="readable-badge">全文可读</span></div><div class="detail-number">${esc(d.number)}</div><h2 id="detail-title">${esc(d.title)}</h2><dl class="detail-meta-grid">${meta.map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${esc(v||'未确认')}</dd></div>`).join('')}</dl><div class="detail-tags">${d.tags.map(t=>`<span>${esc(t)}</span>`).join('')}</div>${d.sourceClass==='reprint'?`<div class="reading-note">正文来自其他官方公开原件，未检到教育部官网对应页面。${esc(d.verificationNote)}</div>`:''}<div class="detail-tabs" role="tablist" aria-label="文件内容"><button class="active" role="tab" id="tab-body" aria-selected="true" aria-controls="panel-body" data-panel="body">正文阅读</button><button role="tab" id="tab-summary" aria-selected="false" aria-controls="panel-summary" tabindex="-1" data-panel="summary">内容提要</button><button role="tab" id="tab-sources" aria-selected="false" aria-controls="panel-sources" tabindex="-1" data-panel="sources">来源与附件</button></div><section class="detail-panel" id="panel-body" role="tabpanel" aria-labelledby="tab-body" data-panel-content="body"><div class="reading-note">完整公文文字快照，段落与排版经过整理。${esc(d.bodyNote||'核心内容直接在本页阅读，附件文字和留存原件见“来源与附件”。')}${d.year<2026?' 本文件保留原始年份，年度任务适用时段以原文为准。':''}</div>${preview?`<div class="source-actions">${localAction(preview,d.localPreviewURL?'查看原件转换预览':'站内预览公开原件')}</div>`:''}${bodyHTML(d.body)}</section><section class="detail-panel" id="panel-summary" role="tabpanel" aria-labelledby="tab-summary" data-panel-content="summary" hidden><h3>文件讲了什么</h3><p class="summary-text">${esc(d.summary)}</p><h3>内容要点</h3><ol class="key-points">${d.points.map(p=>`<li>${esc(typeof p==='string'?p:p.text||p.description||JSON.stringify(p))}</li>`).join('')}</ol><div class="reading-note">摘要、要点与专题标签为本项目整理，不构成官方解读。文件年份、文号序号不等同于政策效力或重要性判断。</div><button class="button button-primary" data-panel="body">阅读全文 →</button></section><section class="detail-panel" id="panel-sources" role="tabpanel" aria-labelledby="tab-sources" data-panel-content="sources" hidden><h3>来源与核验</h3><div class="reading-note">${esc(d.verificationNote||'已核对官方页面标题、发文字号及正文。')}${d.index?`<br>教育部信息索引：${esc(d.index)}`:''}<br>检索日期：${checkedAt}${d.generatedDate?`<br>网页生成日期：${esc(d.generatedDate)}`:''}</div>${sourceRows}${preview?`<div class="source-row"><h3>本站留存原件</h3><div class="source-actions">${localAction(preview,d.localPreviewURL?'站内预览转换版 PDF':'站内预览原件')}${d.localOriginalURL&&d.localPreviewURL?localAction(d.localOriginalURL):''}</div></div>`:''}<h3>相关附件</h3>${attachments||'<p class="reading-note">本文政策内容已在“正文阅读”中完整呈现，暂无单独提取的附件链接。</p>'}<div class="source-row"><small>司局入口</small>${link(dept.url,dept.name)}</div></section><section class="detail-panel" id="panel-preview" data-panel-content="preview" hidden></section>`;
showDialog($('#detail-dialog'));history.replaceState(null,'','#doc='+encodeURIComponent(id));}
function setPanel(name){$$('[data-panel-content]').forEach(p=>p.hidden=p.dataset.panelContent!==name);$$('.detail-tabs [data-panel]').forEach(b=>{const on=b.dataset.panel===name;b.classList.toggle('active',on);b.setAttribute('aria-selected',on);b.tabIndex=on?0:-1;});}
function showPDF(u){if(!activeDoc||!/^files\/[a-f\d]{12}\.pdf$/i.test(u))return;$('#panel-preview').innerHTML=`<div class="preview-heading"><button class="button button-ghost" data-panel="sources">← 返回来源与附件</button><a href="${esc(safeURL(u))}" download class="button button-ghost">下载原件 ↓</a></div><iframe class="pdf-preview" src="${esc(safeURL(u))}#view=FitH" title="${esc(activeDoc.title)}原件预览"></iframe><div class="reading-note">浏览器若不支持 PDF 内嵌预览，可返回正文阅读，或下载留存原件。</div>`;setPanel('preview');$('#panel-preview').scrollIntoView({behavior:'smooth',block:'start'});}
function showAttachment(index){const a=activeDoc?.attachments[index];if(!a?.body)return;$('#panel-preview').innerHTML=`<div class="preview-heading"><button class="button button-ghost" data-panel="sources">← 返回来源与附件</button>${localAction(a.localPreviewURL||a.localURL)}</div><h3>${esc(a.title||a.name||'附件全文')}</h3><div class="reading-note">公开附件的文字提取版，表格版式请结合留存原件核对。</div>${bodyHTML(a.body)}`;setPanel('preview');$('#panel-preview').scrollIntoView({behavior:'smooth',block:'start'});}
function exportCSV(){const rows=[['司局','收录类型','发文字号','年份','文件名称','成文日期','发布日期','专题','内容提要','来源','站内全文链接','检索日期'],...documents.map(d=>[deptById[d.departmentId].name,d.isFirst?'2026 一号文件':'专题政策',d.number,d.year,d.title,d.date,d.publishedDate||'',d.topics.join(' / '),d.summary,d.url,location.origin+location.pathname+'#doc='+d.id,checkedAt])];const csv='\uFEFF'+rows.map(r=>r.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(',')).join('\r\n');const u=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download='产教融合与教育数字化政策索引_'+checkedAt+'.csv';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),10000);toast('已导出全部政策，含站内全文链接');}
$('#stat-depts').textContent=departments.length;$('#stat-docs').textContent=documents.length;$('#stat-first').textContent=documents.filter(d=>d.isFirst).length;$('#dept-count').textContent=departments.length;$('#year').innerHTML='<option value="all">全部年份</option>'+[...new Set(documents.map(d=>d.year))].sort((a,b)=>b-a).map(y=>`<option value="${y}">${y} 年</option>`).join('');
$('#all-departments').onclick=()=>{state.dept='all';render();};$('#search').addEventListener('input',e=>{state.q=e.target.value.trim();render();});for(const key of ['series','sort','year'])$('#'+key).onchange=e=>{state[key]=e.target.value;render();};$('#clear-button').onclick=reset;$('#export-button').onclick=exportCSV;$('#export-button').title='导出全部收录政策及站内链接，不受筛选影响';$('#method-button').onclick=()=>showDialog($('#method-dialog'));$('#back-top').onclick=()=>window.scrollTo({top:0,behavior:'smooth'});$('.brand').onclick=e=>{e.preventDefault();state.view='documents';reset();window.scrollTo({top:0,behavior:'smooth'});};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.dept){state.dept=b.dataset.dept;render();}if(b.dataset.collection){state.collection=b.dataset.collection;render();}if(b.dataset.topic){state.topic=b.dataset.topic;render();}if(b.dataset.view){state.view=b.dataset.view;render();$('#index').scrollIntoView({behavior:'smooth',block:'start'});}if(b.dataset.doc)showDocument(b.dataset.doc);if(b.dataset.coverage){state.view='documents';reset();state.dept=b.dataset.coverage;render();}if(b.hasAttribute('data-reset'))reset();if(b.dataset.panel)setPanel(b.dataset.panel);if(b.dataset.pdf)showPDF(b.dataset.pdf);if(b.dataset.attachment!==undefined)showAttachment(Number(b.dataset.attachment));if(b.dataset.section)$('#'+b.dataset.section)?.scrollIntoView({behavior:'smooth',block:'start'});if(b.classList.contains('close-dialog'))b.closest('dialog').close();});
$$('dialog').forEach(d=>{d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}});d.addEventListener('close',()=>{if(!$$('dialog[open]').length)document.body.classList.remove('modal-open');if(d.id==='detail-dialog'){activeDoc=null;if(location.hash.startsWith('#doc='))history.replaceState(null,'',location.pathname+location.search);}});});
$('#copy-button').onclick=async()=>{try{await navigator.clipboard.writeText(location.href);toast('站内全文链接已复制');}catch{toast('请复制地址栏中的文件链接');}};$('#print-button').onclick=()=>window.print();
document.addEventListener('keydown',e=>{if(e.key==='/'&&!/INPUT|TEXTAREA|SELECT/.test(document.activeElement.tagName)&&!$$('dialog[open]').length){e.preventDefault();$('#search').focus();}if(e.target.matches('.detail-tabs [role="tab"]')&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const tabs=$$('.detail-tabs [role="tab"]');let i=tabs.indexOf(e.target);i=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;setPanel(tabs[i].dataset.panel);tabs[i].focus();}});
window.addEventListener('hashchange',()=>{if(location.hash.startsWith('#doc='))showDocument(decodeURIComponent(location.hash.slice(5)));});render();if(location.hash.startsWith('#doc='))showDocument(decodeURIComponent(location.hash.slice(5)));
